/* ===================================================
   QQ 主题定制 - 顶栏终极版 (带详细修改说明注释)
   =================================================== */

/* === 1. 顶栏整体控制 (底色、毛玻璃、高度) === */
.chat-header-custom:has(.header-profile-section) {
  /* 基础变量锁定（字体颜色、头像变圆等） */
  --chat-header-title-color: #C89546 !important;     
  --chat-header-title-size: 16px !important;         
  --chat-header-title-weight: 600 !important;        
  --chat-header-avatar-size: 34px !important;        /* 头像的大小 */
  --chat-header-avatar-radius: 50% !important;       /* 头像圆角：50%就是正圆形 */
  --chat-header-avatar-border: none !important;

  /* 👇 顶栏的高度，想改顶栏整体有多高，改这里（两处都要一样） 👇 */
  height: 95px !important;
  min-height: 95px !important;
  align-items: center !important;

  /* 顶栏悬浮设置 (不要动这里，保证滑动能穿透) */
  position: absolute !important;
  top: 0 !important; left: 0 !important; right: 0 !important;
  z-index: 100 !important;

   /* 👇 顶栏的颜色和毛玻璃透明度 👇 */
  background: rgba(235, 235, 234, 0.9) !important; /* 🌟 换成这个 */
  backdrop-filter: blur(25px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(25px) saturate(180%) !important;

  /* 顶栏最下方的一根极细高光分隔线 */
  border-bottom: 1px solid rgba(255, 255, 255, 0.05) !important;
}

/* === 2. 消息列表排版 (防止第一条消息被顶栏挡住) === */
.chat-messages-area {
  height: 100% !important;
}
.chat-message-list-custom {
  /* 如果你把顶栏调高了，这里的 55px 也要跟着调大，不然消息会被压住 */
  padding-top: calc(env(safe-area-inset-top, 0px) + 95px) !important;
}

/* === 3. 🌟头像和名字的整体位置 (包含底下的状态也会跟着走) === */
.header-profile-section {
  position: relative !important;

  /* 👇 想改头像和名字的整体位置，就在这里改！ 👇 */
  /* translate(左右像素, 上下像素)。负数代表向左/向上，正数代表向右/向下 */
  /* 比如：translate(-15px, 2px) 就是向左移15px，向下移2px */
  transform: translate(-20px, -5px) !important; 
}

/* === 4. 名字与右侧双贴纸 === */
.chat-header-custom:has(.header-profile-section) .chat-header-title {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  transform: translateY(-8px) !important; 
  white-space: nowrap !important; /* 强制不换行 */

  /* 🌟 给名字加上相对定位，作为贴纸的固定锚点 */
  position: relative !important; 
}

/* 彻底悬浮的右侧贴纸画板 */
.chat-header-custom:has(.header-profile-section) .chat-header-title::after {
  content: "" !important;

  /* 🌟 核心魔法：改成绝对定位，让它彻底脱离排版，不占一丝空间！ */
  position: absolute !important;
  left: 100% !important;          /* 紧紧贴在名字的最右侧 */
  top: 50% !important;            /* 配合向上的Y轴位移，实现垂直居中 */
  transform: translateY(-50%) !important;

  pointer-events: none !important; /* 🌟 防止贴纸挡住底下的按钮点击 */

  /* 画板大小还是 200px，但因为飘起来了，再也不会挤走设置键 */
  margin-left: -15px !important;       
  width: 200px !important;            
  height: 40px !important;           

  /* 贴纸图片和位置 (完全保留你原本调好的参数) */
  background-image: 
    url('https://i.imgant.com/v2/hdAgDDw.png'),  
    url('https://i.imgant.com/v2/V3SwePF.png') !important; 
  background-repeat: no-repeat, no-repeat !important;
  background-size: 63px 23px, 80px 35px !important;  
  background-position: 18px 9px, 80px -1px !important;  
}

/* === 5. 在线状态 & 绿色呼吸灯 === */
/* 隐藏旧状态 */
.chat-header-custom:has(.header-profile-section) .chat-header-subtitle { 
  display: none !important; 
}

/* 强制注入文字：iPhone 17 Pro Max 在线 */
.header-profile-section::after {
  content: "iPhone 17 Pro Max在线" !important;
  position: absolute !important;

  /* 👇 想改“在线文字”的位置，改这里 👇 */
  bottom: -2px !important;          /* 上下位置：负数越大越靠下 */
  left: 56px !important;            /* 左右位置：数值越大越靠右 */

  font-size: 11px !important;       /* 文字大小 */
  color: #000000 !important;        /* 文字颜色 */
  white-space: nowrap !important;
  pointer-events: none !important;
}

/* 强制注入绿色呼吸灯小圆点 */
.header-profile-section::before {
  content: "" !important;
  position: absolute !important;

  /* 👇 想改“绿点”的位置，改这里 👇 */
  bottom: 2px !important;          /* 上下位置 */
  left: 42px !important;            /* 左右位置，需要和上面的文字配合对齐 */

  width: 6px !important;            /* 绿点宽度 */
  height: 6px !important;           /* 绿点高度 */
  border-radius: 50% !important;
  background-color: #10B981 !important; /* 绿点颜色 */
  box-shadow: 0 0 6px rgba(16, 185, 129, 0.6) !important;
  animation: qq-online-pulse 2s infinite ease-in-out !important; 
  pointer-events: none !important;
}

@keyframes qq-online-pulse {
  0% { opacity: 0.5; transform: scale(0.9); box-shadow: 0 0 2px rgba(16, 185, 129, 0.4); }
  50% { opacity: 1; transform: scale(1.1); box-shadow: 0 0 8px rgba(16, 185, 129, 0.9); }
  100% { opacity: 0.5; transform: scale(0.9); box-shadow: 0 0 2px rgba(16, 185, 129, 0.4); }
}

