/* ===================================================
   QQ 主题定制 - 聊天区域终极整合版
   目录：
   1️⃣ 全局气泡颜色与基础设置
   2️⃣ 胶囊气泡与三角小尾巴
   3️⃣ 智能去气泡 (隐藏图片/语音/盲盒的尾巴)
   4️⃣ 独立语音条定制 (白卡+短波形)
   5️⃣ 盲盒长图定制 (点击揭晓)
   6️⃣ 引用消息定制 (自带时间和贴纸)
   7️⃣ 电影字幕级翻译
   8️⃣ 思维链定制 (诗意文案)
   9️⃣ 转账卡片
   =================================================== */

/* =======================================
   1️⃣ 全局气泡颜色与基础设置
   ======================================= */
.chat-detail-screen {
  /* 我方气泡：极浅冰雪蓝 + 黑字 */
  --bubble-me-bg: #F5FAFF !important;      
  --bubble-me-color: #000000 !important;   

  /* 对方气泡：极浅灰白 + 黑字 */
  --bubble-them-bg: #F9F9F9 !important;    
  --bubble-them-color: #000000 !important; 

  /* 气泡内间距，紧凑排版 */
  --bubble-me-padding: 7px 12px !important;
  --bubble-them-padding: 7px 12px !important;

  /* 移除自带边框 */
  --bubble-me-border: none !important;
  --bubble-them-border: none !important;
  /* 🌟 因为气泡变白了，这里加上一层极弱的阴影，让它从背景里浮出来 */
  --bubble-me-shadow: 0 2px 8px rgba(0,0,0,0.04) !important;
  --bubble-them-shadow: 0 2px 8px rgba(0,0,0,0.04) !important;

  /* 全圆角：完美的圆润小胶囊 */
  --bubble-me-radius: 18px !important;
  --bubble-me-radius-first: 18px !important;
  --bubble-me-radius-mid: 18px !important;
  --bubble-me-radius-last: 18px !important;

  --bubble-them-radius: 18px !important;
  --bubble-them-radius-first: 18px !important;
  --bubble-them-radius-mid: 18px !important;
  --bubble-them-radius-last: 18px !important;
}

/* =======================================
   2️⃣ 胶囊气泡与三角小尾巴
   ======================================= */
/* 解除边界裁切 */
.chat-detail-screen .bubble-me-custom,
.chat-detail-screen .bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
}

/* 我方小尾巴 (右下角) */
.chat-detail-screen .bubble-me-custom::before {
  content: "" !important;
  position: absolute !important;
  width: 16px !important;    
  height: 6px !important;    
  bottom: 4px !important;
  right: -5px !important;    
  background: var(--bubble-me-bg) !important;
  clip-path: polygon(50% 0, 0 100%, 100% 100%) !important; 
}

/* 对方小尾巴 (左下角) */
.chat-detail-screen .bubble-them-custom::before {
  content: "" !important;
  position: absolute !important;
  width: 16px !important;
  height: 6px !important;
  bottom: 4px !important;
  left: -5px !important;     
  background: var(--bubble-them-bg) !important;
  clip-path: polygon(50% 0, 0 100%, 100% 100%) !important; 
}

/* =======================================
   3️⃣ 智能去气泡 (精准猎杀单独表情包，绝对防误伤引用)
   ======================================= */

/* 
   核心逻辑：
   1. 侦测常规卡片：语音、盲盒长图、转账、通话
   2. 侦测表情包/图片：只要气泡里包含 img 标签，就判定为表情包
   3. 🌟 绝对防误伤：使用 :not(:has(.msg-reply-block-name))，只要气泡里带有“引用”，就立刻停止透明化，完美保留气泡底色和尾巴！
*/
.chat-detail-screen .bubble-me-custom:has(.voice-msg, .msg-sim-card, .msg-transfer-card, [class*="call" i]),
.chat-detail-screen .bubble-them-custom:has(.voice-msg, .msg-sim-card, .msg-transfer-card, [class*="call" i]),
.chat-detail-screen .bubble-me-custom:has(img):not(:has(.msg-reply-block-name)),
.chat-detail-screen .bubble-them-custom:has(img):not(:has(.msg-reply-block-name)) {
  background: transparent !important;
  padding: 0 !important;
  box-shadow: none !important;
}

/* 强行抹除它们的小尾巴 */
.chat-detail-screen .bubble-me-custom:has(.voice-msg, .msg-sim-card, .msg-transfer-card, [class*="call" i])::before,
.chat-detail-screen .bubble-them-custom:has(.voice-msg, .msg-sim-card, .msg-transfer-card, [class*="call" i])::before,
