}
.chat-detail-screen .voice-msg-me .voice-play-btn svg { fill: #000000 !important; stroke: #000000 !important; }
.chat-detail-screen .voice-msg-them .voice-play-btn svg { fill: #000000 !important; stroke: #000000 !important; }

/* 点击秒数展开文字 (隐形开关) */
.chat-detail-screen .voice-transcription-toggle {
