} 

/* =======================================
   8️⃣ 思维链定制 (诗意文案)
   ======================================= */
.chat-detail-screen {
  /* 按钮文字、箭头、展开后的正文，全都变成静谧灰蓝 */
  --thinking-btn-color: #7AA2D9 !important;
