  font-size: 12px !important;
  letter-spacing: 0.5px !important; 
}

/* =======================================
   💸 9️⃣ QQ 写实版转账卡片 (采纳你的完美架构版)
   ======================================= */

:root {
  /* 🔪 彻底抽空原生黑点底座、各种状态的警示灯和边框 */
  --transfer-icon-bg: transparent !important;
  --transfer-me-icon-bg: transparent !important;
  --transfer-them-icon-bg: transparent !important;
  --transfer-success-icon-bg: transparent !important;
  --transfer-rejected-icon-bg: transparent !important;
  --transfer-expired-icon-bg: transparent !important;
  --transfer-card-border: none !important;
  --transfer-me-card-border: none !important;
  --transfer-them-card-border: none !important;
}

/* === 1. 卡片状态变色 === */
/* 默认状态：QQ 亮蓝 */
.chat-detail-screen .msg-transfer-card {
  width: 220px !important;
  height: 85px !important;
  background-color: #1BA3FF !important; 
  border-radius: 12px !important;        
  position: relative !important;
  padding: 0 !important; 
  overflow: hidden !important; 
  display: block !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
}
/* 已收款状态：浅蓝色 */
.chat-detail-screen .msg-transfer-card.msg-transfer-success {
  background-color: #7BBEFF !important; 
}
/* 拒收 / 过期状态：浅灰色 */
.chat-detail-screen .msg-transfer-card.msg-transfer-rejected,
.chat-detail-screen .msg-transfer-card.msg-transfer-expired-card {
  background-color: #D4D4D4 !important; 
}

/* === 2. 画出底部的极细白线 === */
.chat-detail-screen .msg-transfer-card::before {
  content: "";
  position: absolute;
  bottom: 24px; left: 12px; right: 12px; height: 1px;
  background-color: rgba(255, 255, 255, 0.25) !important;
  transform: scaleY(0.5); /* 压成 0.5px 的极细线 */
  z-index: 1;
}

/* === 3. 隐藏系统默认图标和原生分割线 === */
.chat-detail-screen .msg-transfer-card svg,
.chat-detail-screen .msg-transfer-divider {
  display: none !important;
}

/* === 4. 左侧贴上 QQ 转账贴图 === */
.chat-detail-screen .msg-transfer-card::after {
  content: "";
  position: absolute;
  top: 12px; left: 12px; width: 38px; height: 38px;
  background-image: url('https://i.imgant.com/v2/r7FlGkx.png');
  background-size: 100% 100%; background-repeat: no-repeat; z-index: 2;
}

/* === 5. 调整金额文字 (强制染白，破除系统变黑诅咒) === */
.chat-detail-screen .msg-transfer-amount {
  position: absolute !important;
  top: 14px !important;
  left: 60px !important;      
  z-index: 2 !important;
  display: flex !important;           
  flex-direction: row !important;
  align-items: baseline !important;   
  white-space: nowrap !important;     
}
.chat-detail-screen .msg-transfer-amount,
.chat-detail-screen .msg-transfer-amount * {
  color: #ffffff !important;  
  -webkit-text-fill-color: #ffffff !important; /* 🌟 强制填充色，绝对白！ */
  font-size: 16px !important;
  font-weight: bold !important;
  line-height: 1 !important;
  background: transparent !important; 
}

/* === 6. 自定义备注文字：眼泪好烫... === */
.chat-detail-screen .msg-transfer-label {
  position: absolute !important; 
  top: 36px !important;            
  left: 60px !important;
  z-index: 2 !important; 
  font-size: 0 !important; /* 🌟 隐藏系统原生文本 */
}
.chat-detail-screen .msg-transfer-label::after {
  content: "眼泪好烫 爱也是这个温度吗" !important;
  color: rgba(255, 255, 255, 0.8) !important; 
  -webkit-text-fill-color: rgba(255, 255, 255, 0.8) !important; 
  font-size: 12px !important; 
}

/* === 7. 底部写上“转账”二字 === */
.chat-detail-screen .msg-transfer-status-text {
  position: absolute !important; bottom: 5px !important; left: 14px !important; font-size: 0 !important; z-index: 2 !important; margin: 0 !important; padding: 0 !important; background: transparent !important;
}
.chat-detail-screen .msg-transfer-status-text::after {
  content: "转账" !important; font-size: 11px !important; color: #ffffff !important; -webkit-text-fill-color: #ffffff !important; 
}

/* === 8. 终极物理清理机：彻底隐藏多余系统垃圾 === */

/* 1. 扩大暗杀名单：把倒计时可能用到的 class 全部抹除 */
.chat-detail-screen .msg-transfer-subtitle,
.chat-detail-screen .msg-transfer-card [class*="expire" i],
.chat-detail-screen .msg-transfer-card [class*="time" i],
.chat-detail-screen .msg-transfer-card [class*="count" i], /* 狙击 countdown */
.chat-detail-screen .msg-transfer-card [class*="timer" i], /* 狙击 timer */
.chat-detail-screen .msg-transfer-card [class*="note" i],  /* 狙击 note */
.chat-detail-screen .msg-transfer-card [class*="dot" i],
.chat-detail-screen .msg-transfer-card [class*="unread" i],
.chat-detail-screen .msg-transfer-status-text *,
.chat-detail-screen .msg-transfer-label * {
  display: none !important; 
}

/* 2. 核弹级兜底：把卡片里所有未知的文字强制变透明（排除你保留的核心元素） */
.chat-detail-screen .msg-transfer-card *:not(.msg-transfer-amount):not(.msg-transfer-amount *):not(.msg-transfer-label):not(.msg-transfer-status-text) {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  font-size: 0 !important;
  letter-spacing: -999px !important;
}

/* 为了防止原生卡片自动拉长导致底部露馅，死死锁住高度和溢出 */
.chat-detail-screen .msg-transfer-card {
  max-height: 85px !important;
  min-height: 85px !important;
}

