    --bubble-me-bg-gradient: initial;
    --bubble-me-color: #ffffff;
    --bubble-me-border: 1px solid rgba(255, 255, 255, 0.25);
    --bubble-me-shadow: 0 2px 12px rgba(11, 132, 255, 0.2), inset 0 1px 0 rgba(255,255,255,0.2);
    --bubble-me-radius: 20px;
